(2403675, 330589, 18197, '<td valign="top">Nice subject well captured, exposed, focused and presented. Seems to tilt to the left which distracts a bit. May be an optical illusion.</td>', 'Nice subject well captured, exposed, focused and presented. Seems to tilt to the left which distracts a bit. May be an optical illusion.', '2006-05-10 21:13:27.000000', NULL, 1),
(2403676, 332387, 51538, '<td valign="top">I like the dramatic effect.</td>', 'I like the dramatic effect.', '2006-05-10 21:13:29.000000', NULL, 1),
