(2404262, 330298, 24659, '<td valign="top">You got the shot I was too lazy to drive to make!  Nicely done! 9.</td>', 'You got the shot I was too lazy to drive to make!  Nicely done! 9.', '2006-05-10 23:51:33.000000', NULL, 1),
(2404304, 331897, 16829, '<td valign="top">A great composition</td>', 'A great composition', '2006-05-10 23:59:33.000000', NULL, 1),
