(2406656, 331143, 37879, '<td valign="top">nice composition...perhaps a smaller aperature would bring more "pop" to the image.</td>', 'nice composition...perhaps a smaller aperature would bring more "pop" to the image.', '2006-05-11 17:19:53.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2406663, 332219, 46428, '<td valign="top">Cool.</td>', 'Cool.', '2006-05-11 17:20:56.000000', NULL, 1),
(2406670, 329572, 37879, '<td valign="top">very original...this feels like a true piece of art.  I love the noise...not so crazy about the 2 "extra" shadows...the pink in the ankles looks a little too much like Peptobismol (sp?)...why doesn''t it have grain like the rest of the image?  nice work</td>', 'very original...this feels like a true piece of art.  I love the noise...not so crazy about the 2 "extra" shadows...the pink in the ankles looks a little too much like Peptobismol (sp?)...why doesn''t it have grain like the rest of the image?  nice work', '2006-05-11 17:23:21.000000', NULL, 1),
(2406671, 331053, 49326, '<td valign="top">Very nice reflection on the water</td>', 'Very nice reflection on the water', '2006-05-11 17:23:28.000000', NULL, 1),
(2406674, 331858, 37879, '<td valign="top">very cool...this will surely make the top 10</td>', 'very cool...this will surely make the top 10', '2006-05-11 17:24:07.000000', NULL, 1),
