(2409402, 331916, 7291, '<td valign="top">That''s just creepy.</td>', 'That''s just creepy.', '2006-05-12 12:59:58.000000', NULL, 1),
(2409409, 330552, 7291, '<td valign="top">Hmmm...interesting.  Out of focus fireworks.  I can see how that might work but I''m not sure it''s workig here.  I may have to come back to this one.</td>', 'Hmmm...interesting.  Out of focus fireworks.  I can see how that might work but I''m not sure it''s workig here.  I may have to come back to this one.', '2006-05-12 13:01:55.000000', NULL, 1),
(2409416, 332181, 7291, '<td valign="top">Wow.  Color, perspective, leading lines, a hint of fog...it''s all here.  Good work!</td>', 'Wow.  Color, perspective, leading lines, a hint of fog...it''s all here.  Good work!', '2006-05-12 13:05:06.000000', NULL, 1),
(2409419, 331974, 7291, '<td valign="top">What!?  Didn''t I already see this in the challenge?  In any case, thise one is better excecuted than the previous one I saw.  However, the neon yellow sign on the upper right is very distracting.</td>', 'What!?  Didn''t I already see this in the challenge?  In any case, thise one is better excecuted than the previous one I saw.  However, the neon yellow sign on the upper right is very distracting.', '2006-05-12 13:06:39.000000', NULL, 1),
