(2415679, 330352, 41574, '<td valign="top">One of my favorites, so far; I absolutely love it. Great work!</td>', 'One of my favorites, so far; I absolutely love it. Great work!', '2006-05-15 00:28:21.000000', NULL, 1),
(2415684, 330827, 41574, '<td valign="top">I feel that the bottom could have been cropped somewhat, but rather like the shot, nonetheless. Good work.</td>', 'I feel that the bottom could have been cropped somewhat, but rather like the shot, nonetheless. Good work.', '2006-05-15 00:29:00.000000', NULL, 1),
(2415687, 332318, 41574, '<td valign="top">It looks like something that should have seeb in a "Star Wars" movie, but nothing''s in focus...</td>', 'It looks like something that should have seeb in a "Star Wars" movie, but nothing''s in focus...', '2006-05-15 00:29:32.000000', NULL, 1),
(2415694, 331093, 41574, '<td valign="top">Ever-so-slightly tilted horizon, but, nonetheless, amazing shot; I just love the clarity and sharpness. Great job!</td>', 'Ever-so-slightly tilted horizon, but, nonetheless, amazing shot; I just love the clarity and sharpness. Great job!', '2006-05-15 00:30:40.000000', NULL, 1),
